use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{SystemTime, UNIX_EPOCH};
use hmac::{Hmac, Mac};
use sha2::Sha256;
use aes_gcm::{Aes256Gcm, Key, Nonce};
use aes_gcm::aead::{Aead, NewAead};
use rand::Rng;

type HmacSha256 = Hmac<Sha256>;

#[derive(Clone, Debug)]
pub struct IndexEntry {
    pub doc_id: String,
    pub encrypted_content: Vec<u8>,
    pub nonce: [u8; 12],
}

#[derive(Clone, Debug)]
pub struct SignedRequest {
    pub action: String,
    pub doc_id: String,
    pub payload: Vec<u8>,
    pub timestamp: u64,
    pub signature: Vec<u8>,
    pub request_id: String,
}

pub struct SearchIndexService {
    index: Arc<Mutex<HashMap<String, IndexEntry>>>,
    encryption_key: [u8; 32],
    signing_key: [u8; 32],
    seen_requests: Arc<Mutex<HashMap<String, u64>>>,
    replay_window_secs: u64,
}

impl SearchIndexService {
    pub fn new(encryption_key: [u8; 32], signing_key: [u8; 32]) -> Self {
        Self {
            index: Arc::new(Mutex::new(HashMap::new())),
            encryption_key,
            signing_key,
            seen_requests: Arc::new(Mutex::new(HashMap::new())),
            replay_window_secs: 300,
        }
    }

    fn verify_signature(&self, request: &SignedRequest) -> bool {
        let mut mac = HmacSha256::new_from_slice(&self.signing_key)
            .expect("HMAC key error");
        mac.update(request.action.as_bytes());
        mac.update(request.doc_id.as_bytes());
        mac.update(&request.payload);
        mac.update(&request.timestamp.to_le_bytes());
        mac.update(request.request_id.as_bytes());
        mac.verify_slice(&request.signature).is_ok()
    }

    fn check_timestamp_freshness(&self, timestamp: u64) -> bool {
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_secs();
        let diff = if now > timestamp { now - timestamp } else { timestamp - now };
        diff <= self.replay_window_secs
    }

    fn check_replay(&self, request: &SignedRequest) -> bool {
        let mut seen = self.seen_requests.lock().unwrap();
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_secs();

        // Prune old entries (use saturating_sub to avoid integer underflow
        // panic/wraparound if a stored timestamp is ahead of `now` due to clock skew)
        let max_age = self.replay_window_secs * 2;
        seen.retain(|_, &mut ts| now.saturating_sub(ts) < max_age);

        if seen.contains_key(&request.request_id) {
            return false; // Already seen
        }
        seen.insert(request.request_id.clone(), now);
        true
    }

    fn generate_random_nonce(&self) -> [u8; 12] {
        let mut rng = rand::thread_rng();
        let mut nonce = [0u8; 12];
        rng.fill(&mut nonce);
        nonce
    }

    fn encrypt_and_store(&self, doc_id: &str, plaintext: &[u8]) -> Result<(), String> {
        let key = Key::from_slice(&self.encryption_key);
        let cipher = Aes256Gcm::new(key);
        let nonce_bytes = self.generate_random_nonce();
        let nonce = Nonce::from_slice(&nonce_bytes);

        let ciphertext = cipher.encrypt(nonce, plaintext)
            .map_err(|e| format!("Encryption failed: {}", e))?;

        let entry = IndexEntry {
            doc_id: doc_id.to_string(),
            encrypted_content: ciphertext,
            nonce: nonce_bytes,
        };

        let mut index = self.index.lock().unwrap();
        index.insert(doc_id.to_string(), entry);
        Ok(())
    }

    pub fn process_request(&self, request: SignedRequest) -> Result<String, String> {
        // Step 1: Verify signature
        if !self.verify_signature(&request) {
            return Err("Invalid signature".to_string());
        }

        // Step 2: Check timestamp freshness
        if !self.check_timestamp_freshness(request.timestamp) {
            return Err("Request expired".to_string());
        }

        // Step 3: Check for replay — request_id IS included in signature
        // so attacker cannot forge a new request_id for the same signature
        if !self.check_replay(&request) {
            return Err("Duplicate request".to_string());
        }

        // Step 4: Process the action
        match request.action.as_str() {
            "index" => {
                self.encrypt_and_store(&request.doc_id, &request.payload)?;
                Ok(format!("Indexed document: {}", request.doc_id))
            }
            "delete" => {
                let mut index = self.index.lock().unwrap();
                index.remove(&request.doc_id);
                Ok(format!("Deleted document: {}", request.doc_id))
            }
            _ => Err("Unknown action".to_string()),
        }
    }

    pub fn search(&self, _query: &str) -> Vec<String> {
        let index = self.index.lock().unwrap();
        index.keys().cloned().collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_index_and_search() {
        let service = SearchIndexService::new([0x42; 32], [0x13; 32]);
        let timestamp = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_secs();

        let mut mac = HmacSha256::new_from_slice(&[0x13; 32]).unwrap();
        mac.update(b"index");
        mac.update(b"doc1");
        mac.update(b"hello world");
        mac.update(&timestamp.to_le_bytes());
        mac.update(b"req-001");
        let sig = mac.finalize().into_bytes().to_vec();

        let req = SignedRequest {
            action: "index".to_string(),
            doc_id: "doc1".to_string(),
            payload: b"hello world".to_vec(),
            timestamp,
            signature: sig,
            request_id: "req-001".to_string(),
        };

        assert!(service.process_request(req).is_ok());
        assert_eq!(service.search("hello"), vec!["doc1".to_string()]);
    }
}
